import { backendFetch } from "@/lib/backend";
import { newCardSchema } from "@/lib/schemas";
import { privateJson } from "@/server/api";
import { getCardSettings } from "@/server/dashboard-data";

/**
 * GET /api/cards
 * Monthly limits, usage and freeze state per card.
 */
export async function GET() {
  return privateJson(() => getCardSettings());
}

/**
 * POST /api/cards
 * Issues a virtual card linked to the user's wallet in the chosen currency.
 * The number, expiry and limits are generated by the API, never by the browser.
 */
export async function POST(request: Request) {
  const parsed = newCardSchema.safeParse(await request.json().catch(() => null));

  if (!parsed.success) {
    return Response.json(
      { error: "VALIDATION_ERROR", message: parsed.error.issues[0]?.message ?? "Check the card details." },
      { status: 400 },
    );
  }

  const { label, holder, brand, currency, variant } = parsed.data;

  return privateJson(
    () =>
      backendFetch("/cards", {
        method: "POST",
        body: {
          type: "VIRTUAL",
          brand: brand.toUpperCase(),
          variant: variant.toUpperCase(),
          label,
          holderName: holder,
          currencyCode: currency,
        },
      }),
    { status: 201 },
  );
}
